-- Origen SINTÉTICO mínimo para validar la aplicación sin el conjunto real (ver docs/verificacion.md).
-- Ningún valor proviene del colegio. NO sirve para `pnpm db:verify` ni para medir: sus conteos son otros.
-- Las columnas se dedujeron de las consultas de la aplicación; el dump real sigue siendo la referencia.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS ciclos (anio SMALLINT PRIMARY KEY, nombre VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS estudiantes (estudiante_id VARCHAR(24) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS secciones (seccion_id VARCHAR(24) PRIMARY KEY, anio SMALLINT NOT NULL, nivel VARCHAR(30), grado VARCHAR(30) NOT NULL, seccion VARCHAR(10) NOT NULL, grado_fuente VARCHAR(30));
CREATE TABLE IF NOT EXISTS asignaturas (asignatura_id VARCHAR(24) PRIMARY KEY, nombre VARCHAR(80) NOT NULL, nombre_fuente VARCHAR(80), espacio_inicial_fuente TINYINT(1));
CREATE TABLE IF NOT EXISTS periodos (periodo_id VARCHAR(24) PRIMARY KEY, anio SMALLINT NOT NULL, numero TINYINT NOT NULL, nombre VARCHAR(40) NOT NULL, fecha_inicio DATE, fecha_fin DATE);
CREATE TABLE IF NOT EXISTS ofertas (oferta_id VARCHAR(24) PRIMARY KEY, seccion_id VARCHAR(24) NOT NULL, asignatura_id VARCHAR(24) NOT NULL, anio SMALLINT NOT NULL);
CREATE TABLE IF NOT EXISTS fuentes (fuente_id VARCHAR(24) PRIMARY KEY, archivo VARCHAR(120) NOT NULL, tipo VARCHAR(30) NOT NULL, anio SMALLINT NOT NULL, filas_fuente INT NOT NULL, sha256 CHAR(64) NOT NULL, fecha_min DATE, fecha_max DATE);
CREATE TABLE IF NOT EXISTS matriculas (matricula_id VARCHAR(24) PRIMARY KEY, estudiante_id VARCHAR(24) NOT NULL, seccion_id VARCHAR(24) NOT NULL, anio SMALLINT NOT NULL, estado VARCHAR(30), fuente_id VARCHAR(24) NOT NULL, hoja_fuente VARCHAR(60) NOT NULL, fila_fuente INT NOT NULL);
CREATE TABLE IF NOT EXISTS asistencias (asistencia_id VARCHAR(24) PRIMARY KEY, estudiante_id VARCHAR(24) NOT NULL, seccion_id VARCHAR(24) NOT NULL, anio SMALLINT NOT NULL, fecha DATE NOT NULL, estado_codigo VARCHAR(8) NOT NULL, estado VARCHAR(40) NOT NULL, fuente_id VARCHAR(24) NOT NULL, hoja_fuente VARCHAR(60) NOT NULL, fila_fuente INT NOT NULL, columna_fuente INT NOT NULL, KEY idx_asistencia_fecha (anio, fecha));
CREATE TABLE IF NOT EXISTS calificaciones (calificacion_id VARCHAR(24) PRIMARY KEY, estudiante_id VARCHAR(24) NOT NULL, oferta_id VARCHAR(24) NOT NULL, periodo_id VARCHAR(24) NOT NULL, anio SMALLINT NOT NULL, valor_fuente VARCHAR(40), valor_numerico DECIMAL(10,4), registrada TINYINT(1) NOT NULL, nivel_agregacion VARCHAR(30) NOT NULL, fuente_id VARCHAR(24) NOT NULL, hoja_fuente VARCHAR(60) NOT NULL, fila_fuente INT NOT NULL, columna_fuente INT NOT NULL);
CREATE TABLE IF NOT EXISTS controles (control_id INT PRIMARY KEY, fuente_id VARCHAR(24) NOT NULL, anio SMALLINT NOT NULL, grupo VARCHAR(40) NOT NULL, tipo VARCHAR(30) NOT NULL, estado_codigo VARCHAR(8), extraido INT NOT NULL, total_fuente INT NOT NULL, diferencia INT NOT NULL, coincide TINYINT(1) NOT NULL);
